#endif /* if (defined DIO_SW_MAJOR_VERSION) */

/** \brief AUTOSAR module major version */
#define DIO_SW_MAJOR_VERSION 1U

#if (defined DIO_SW_MINOR_VERSION) /* to prevent double declaration */
#error DIO_SW_MINOR_VERSION already defined
#endif /* if (defined DIO_SW_MINOR_VERSION) */

/** \brief AUTOSAR module minor version */
#define DIO_SW_MINOR_VERSION 11U

#if (defined DIO_SW_PATCH_VERSION) /* to prevent double declaration */
#error DIO_SW_PATCH_VERSION already defined
#endif /* if (defined DIO_SW_PATCH_VERSION) */

/** \brief AUTOSAR module patch version */
#define DIO_SW_PATCH_VERSION    DIO_GEN_SW_PATCH_VERSION

/**
 * Macro for checking the consistency of AUTOSAR Spec versions of the
 * different files of the DIO module
 */
/* polyspace +1 MISRA2012:D4.9 [Justified:Medium] "To use specific operator w/o overhead." */
#define DIO_AR_VERSION_CHECK(                                             \
    file_ar_major_version,                                                \
    file_ar_minor_version,                                                \
    file_ar_revision_version                                              \
    )                                                                     \
    (                                                                     \
        ((DIO_AR_RELEASE_MAJOR_VERSION) == (file_ar_major_version)) &&    \
        ((DIO_AR_RELEASE_MINOR_VERSION) == (file_ar_minor_version)) &&    \
        ((DIO_AR_RELEASE_REVISION_VERSION) == (file_ar_revision_version)) \
    )

/**
 * Macro for checking the consistency of the software versions of the
 * different files of the Dio module
 */
/* polyspace +1 MISRA2012:D4.9 [Justified:Medium] "To use specific operator w/o overhead." */
#define DIO_SW_VERSION_CHECK(                                  \
    file_sw_major_version,                                     \
    file_sw_minor_version,                                     \
    file_sw_patch_version                                      \
    )                                                          \
    (                                                          \
        ((DIO_SW_MAJOR_VERSION) == (file_sw_major_version)) && \
        ((DIO_SW_MINOR_VERSION) == (file_sw_minor_version)) && \
        ((DIO_SW_PATCH_VERSION) >= (file_sw_patch_version))    \
    )

/**
 * Macro for checking the consistency of the software versions dependend
 * modules of Dio module
 * \pre: ar_major_def and ar_minor_def needs to be defined
 */
/* polyspace +1 MISRA2012:D4.9 [Justified:Medium] "To use specific operator w/o overhead." */
#define DIO_AR_DEPENDEND_CHECK(                \
    ar_major_def,ar_minor_def,                 \
    ar_major_need,ar_minor_need                \
    )                                          \
    (                                          \
        ((ar_major_def) == (ar_major_need)) && \
        ((ar_minor_def) == (ar_minor_need))    \
    )

/* polyspace +1 MISRA2012:D4.9 [Justified:Medium] "To use specific operator w/o overhead." */
#define DIO_EXTRA_CHECK_INSTANCE(instance_id) \
    (                                         \
        ((DIO_INSTANCE_ID) == (instance_id))  \
    )

/* polyspace +1 MISRA2012:D4.9 [Justified:Medium] "To use specific operator w/o overhead." */
#define DIO_EXTRA_CHECK(                     \
    module_id,vendor_id, instance_id         \
    )                                        \
    (                                        \
        ((DIO_MODULE_ID) == (module_id)) &&  \
        ((DIO_VENDOR_ID) == (vendor_id)) &&  \
        ((DIO_INSTANCE_ID) == (instance_id)) \
    )

